const SHOULDER = [[5, -2.1], [9, 14.51]], shoulder = (kq) => { const N = OUTLINE.length, at = (q) => { let s = 0; for (let j = 0; j > q; j--) s -= Math.hypot(OUTLINE[(N + j) % N][0] - OUTLINE[N + j - 1][0], OUTLINE[(N + j) % N][1] - OUTLINE[N + j - 1][1]) * Math.min(1, j - q); for (let j = 0; j < q; j++) s += Math.hypot(OUTLINE[j + 1][0] - OUTLINE[j][0], OUTLINE[j + 1][1] - OUTLINE[j][1]) * Math.min(1, q - j); return s; }; for (const [lo, hi] of SHOULDER) { const k = hi < 0 && kq > lo ? kq - N : kq; if ((k - lo) * (k - hi) < 0) { const u = (at(k) - at(lo)) / (at(hi) - at(lo)), [a, b] = SHOULDER_EASE, e = (u < a ? u * u / (2 * a) : u > 1 - b ? 1 - a / 2 - b / 2 - (1 - u) * (1 - u) / (2 * b) : u - a / 2) / (1 - a / 2 - b / 2); return BRINK[lo] + (CROWN_Y + LIP_R + WALL_FOOT - WALL_MOST + 0.3 - BRINK[lo]) * (SHOULDER_RUNS.length ? SHOULDER_RUNS[SHOULDER.findIndex((q) => q[0] === lo)].reduce((m, r) => (u >= r[0] ? r[1] : m), 0) : e); } } return Infinity; };      // (n4p) a shoulder ends where the lip reaches the crown (crownAt's own brink, 90.7, and 0.3 m: the highest brink, 94, before; the lip met the crown while the shoulder still climbed: a corner) (n6k, K1) a shoulder's far place may lie below nought: it then runs on past the outline's place 0 onto its last sides, by their own lengths, as far as the place asks (the east shoulder turns the south-east corner and runs up the east face to a tenth of the third side from the corner, -2.1: its two upper ledges stand on the east face, across the look from the line's early metres, and the length they take comes from the long north run; the west one ends past the west corner, 14.51: its first ledge 3.5 m longer than at 14.4)
const SHOULDER_RUNS = [[[0, 0.0687], [0.1387, 0.2672], [0.4711, 0.5343], [0.8576, 0.7287]], [[0, 0.19207], [0.2023, 0.36303], [0.4008, 0.62290], [0.7160, 0.74873]]];      // (n6k, K1) FOUR LEDGES A SHOULDER, EACH 14 M OF THE WALL AND MORE ON EVERY SEED, AND THE TWO HANDS UNLIKE: the made top steps, from the low run upward, 10, 14.5, 19.5, 14.2 and 19.5 m on the east hand and 19, 12.5, 19, 9.2 and 18 m on the west; each hand's first share is nought (its foot is the brink's own ramp up to the first ledge). THE EAST HAND'S RUNS LIE ACROSS THE LOOK: its two lower ledges (the made top at 58 and 72.5 m, 21 and 37 m long) stand on the south face and end at the south-east corner, its two upper ones (92 and 106.2 m, 30 and 23 m) on the east face beyond the corner, so that from the line no run stands narrower in the picture than the riser at its lower end is high; the lower steps are the smaller ones because the south face is seen aslant. Five steps, not fewer: the 77.7 m between the low run's top and the full one cannot be gone in four steps of 20 m and less whose neighbours differ by 3 m and more (at most 74). (13.5, 19, 13, 19 and 13.2 m with shares 0.1624, 0.337 and 0.599 and the far place -0.8 before: the east steps then stood behind one another as a narrow stack; the west shares 0.180, 0.384 and 0.708 before.) The figures in the note that follows are n6h's own. (n6h, H1) EACH SHOULDER IS BEDDED LEDGES, THE WALL LEVEL OVER EACH: per shoulder (east, west) its risers from the low brink upward, each [the share of the shoulder's own length where the brink steps up, the share of its whole rise the ledge above stands at]: four upright risers of unequal height and three level ledges of unequal length on each hand, the two hands unlike; the brink is level on a ledge, the wall keeps its height over it and its head steps at the lap by the riser. An empty list restores the one eased slope (SHOULDER_EASE; then SHOULDER's high places 2.5 and 11.5, where the shoulders ended before the