// THE WAY IN: LINE.run m straight on the compass heading LINE.from, then one bend to starboard of LINE.inR m onto the first side, ending LINE.join m along it; the last side is flown LINE.last m.
export function linePoints() {
  const Q = LINE, pts = [];      // (n5y) the line from its typed first point and heading by its pieces (x east, z south); no posts
  const dir = (c) => [Math.sin(c * D2R), -Math.cos(c * D2R)], stb = (c) => [Math.cos(c * D2R), Math.sin(c * D2R)];      // a heading's own direction, and starboard of it
  let c = Q.from, x = Q.start[0], z = Q.start[1];
  let len = 0; const J = [], push = () => { if (pts.length) { const a = pts[pts.length - 1]; len += Math.hypot(x - a[0], z - a[2]); } pts.push([x, Q.eye, z]); };      // J: the line's own metre where each piece ends (J[0]: the kept points of the first side)
  const line = (len, upTo) => { const k = Math.max(1, Math.round(len / Q.step)), d = dir(c), x0 = x, z0 = z; for (let i = 1; i <= (upTo || k); i++) { x = x0 + d[0] * len * i / k; z = z0 + d[1] * len * i / k; push(); } };
  const arc = (ax, az, R, c1, sg, upTo) => { const k = Math.max(2, Math.round(R * Math.abs(c1 - c) * D2R / Q.step)), c0 = c; for (let i = 1; i <= k; i++) { c = c0 + (c1 - c0) * i / k; const s = stb(c), x1 = ax - sg * R * s[0], z1 = az - sg * R * s[1], d = Math.hypot(x1 - x, z1 - z); if (upTo && len + d > upTo) { const t = (upTo - len) / d; c = Math.atan2(x1 - x, -(z1 - z)) / D2R; x += (x1 - x) * t; z += (z1 - z) * t; push(); return; } x = x1; z = z1; push(); } };      // upTo: the bend is left at this metre of the line, on its own chord and on that chord's heading (the built points before it stand float for float)      // sg 1: the arc's middle to starboard (a turn to starboard); -1: to port
  push(); J.push(len);      // (n5y) the line's first point; J[0] is nought
  for (const pc of Q.pieces) { if (pc[0] === 'S') line(pc[1]); else { const sg = pc[0] === 'R' ? 1 : -1, s0 = stb(c); let c1 = pc[2]; while (sg > 0 && c1 < c) c1 += 360; while (sg < 0 && c1 > c) c1 -= 360; while (sg > 0 && c1 - 360 >= c) c1 -= 360; while (sg < 0 && c1 + 360 <= c) c1 += 360; arc(x + sg * pc[1] * s0[0], z + sg * pc[1] * s0[1], pc[1], c1, sg); } J.push(len); }      // a bend turns less than one round, whatever rounds the heading has gathered
  pts.joints = J; return pts;
}
// (r21, D6, the lead's order) THE VISIT BEGINS LINE.begin m IN ALONG THE LINE (as the meadow's does): the line itself is laid as before and ITS OWN METRES ARE UNCHANGED (every body's place, every knot and every figure of this file and of the
// world file is still a metre of the whole line); the flown path is the line from its metre LINE.begin on, and every law reads the line's metre as LINE.begin plus the path's own. The time saved is not added back (the pace is kept).
// LINE.begin is typed, the same on every seed: about where the birds' ledges (the near body, 115 m down the line, 24 to 28 m tall, their face 14 to 15 m to port of the line) come to stand a third of the picture's height. (r21, stage E: the line is laid anew, LINE.posts; its metres are its own as before and LINE.begin is kept.)
export function visitPoints() {
  const pts = linePoints(), out = []; let m = 0;
  for (let i = 1; i < pts.length; i++) { const a = pts[i - 1], b = pts[i], d = Math.hypot(b[0] - a[0], b[2] - a[2]); if (m + d > LINE.begin) { if (!out.length) { const t = (LINE.begin - m) / d; out.push([a[0] + (b[0] - a[0]) * t, a[1], a[2] + (b[2] - a[2]) * t]); } out.push(b); } m += d; }
  return out;
}

