// (n5x, X3) THE LAPS' RUNS (see RUNS): each lap's place on the brink in the coast's own metres (the nearest column's, carried along to its neighbour), written into one row of figures: how near the lap (0 to 1 across the run's own half breadth), the run's own length (0 to 1), green or dark
function lapRuns(P) {
  const R = RUNS, n = R.n, data = new Uint8Array(n * 4), c = P.cols, NC = c.length, per = P.perim, W = P.wall, rr = makeRng(hashSeed('runs:' + P.seed));
  for (const q of W.sheets) { const p = W.at(q.t0); let b = 1e18, j = 0; for (let i = 0; i < NC; i++) { const d = (c[i].bx - p.x) ** 2 + (c[i].bz - p.z) ** 2; if (d < b) { b = d; j = i; } }
    const a = c[j], nb = c[(j + 1) % NC], pv = c[(j + NC - 1) % NC], along = (o) => ((p.x - a.bx) * (o.bx - a.bx) + (p.z - a.bz) * (o.bz - a.bz)) / Math.max(1e-6, (o.bx - a.bx) ** 2 + (o.bz - a.bz) ** 2), un = along(nb), up = along(pv);
    const s0 = un > 0 ? a.s + Math.min(1, un) * (((nb.s - a.s) % per + per) % per) : a.s - Math.min(1, Math.max(0, up)) * (((a.s - pv.s) % per + per) % per), hw = rr.range(R.half[0], R.half[1]), len = Math.round(255 * rr()), grn = rr() < R.share ? 255 : 0;
    for (let i = 0; i < n; i++) { const si = (i + 0.5) * R.span / n; if (si >= per) break; const d = Math.abs(si - ((s0 % per) + per) % per), v = Math.round(255 * clamp(1 - Math.min(d, per - d) / hw, 0, 1)); if (v > data[i * 4]) { data[i * 4] = v; data[i * 4 + 1] = len; data[i * 4 + 2] = grn; data[i * 4 + 3] = 255; } } }
  const t = new THREE.DataTexture(data, n, 1, THREE.RGBAFormat); t.magFilter = t.minFilter = THREE.LinearFilter; t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping; t.generateMipmaps = false; t.needsUpdate = true; return t;
}

// THE WALL (fourteenth pass; as it stands since the twentieth): ONE WALL OF OLD BRONZE all round, from the rock under it to ONE CROWN LINE (CROWN_Y in the island's own frame, the same all
// round: it tilts with the list against the horizon); ITS HEAD A PLAIN UPPER EDGE under a flat capping sheet (HEAD: no rolled lip), level over each sheet on the level stretches and raked with the lip on the two shoulders (SHEETS, RAKE); NO HOOP (HOOPS is empty since the seventeenth pass: one tier); IT IS BUILT OF GREAT UPRIGHT SHEETS 5 to 14 m broad, each one piece from foot to head, and its paint takes each sheet from the mesh:
// a hair-fine upright seam at every built lap, each sheet of its own tone, rub and polish (PLATES; its w and course and COURSES' h and w are still read by the paint's old cell law, which draws nothing now; no heads since r21: rows of rivet heads stood again from stage D to stage F and are out since STAGE G, with the band's level seams: one tier, no dots), the sun's flash by plain optics (FLASH), and verdigris hanging in streaks from the head; no course, no post, no buttress, no gate, no opening (r21, stage F, F4: GREAT UPRIGHT RIBS of the same metal are drawn in its paint at unequal spacing, each with its shade beside it away from the sun: RIBS; it is one wall still, of one metal, with no gate and no opening). Its height is the
// crown less the brink under it. One section swept round the smooth plan: the skin (with a half round for each entry of HOOPS: none), the capping sheet, the inner face; each sheet its own piece of it under its own head.
